-- 2026-11-19: the Spotlight outreach order (playbook ve-podcast-studio). Safe to run twice.
insert into playbook_records (slug, brand_slug, author, body, source, kind, created_at)
select 've-podcast-studio', 'vegans-explore', 'Logan', $b$Spotlight outreach order, Sean 2026-11-19: "once we get the clips locked in, even before it's on the podcast, we want to send an email out to those people and let them know what's coming up, let them know about the collaboration, just sort it all out before we go live." An (Sen Saigon) goes live about Monday Nov 23 ("so we can follow up with her since she's already kind of warm"), after Ep 147 Sun Nov 22; Veronica (Love Life Cafe) a week later. Contacts on file: sensaigon.nyc@gmail.com (ve_outreach_contacts); veronica@lovelifecafe.com (ve_outreach_contacts, GHL export), neither on do-not-contact. Plan: Sean locks the two reels; Logan drafts the email as a BrandDesk Outreach program (Podcast Spotlight), the reel behind a tracked /go/ link; Sean approves; An's goes out by Fri Nov 20 (two days before Sunday), Veronica's by Tue Nov 24.$b$, 'text', 'decision', now()
where not exists (select 1 from playbook_records where slug='ve-podcast-studio' and body like 'Spotlight outreach order, Sean 2026-11-19%');
